**Plan**
- A `CharacterController` moves on the world X/Z plane from WASD with smoothed acceleration and manual gravity.
- Each frame the mouse position becomes a ray from the camera that is intersected with a horizontal `Plane` at the character's height; that hit point is the aim point.
- The character turns toward the aim point at a limited turn speed, and an optional follow camera keeps a fixed top-down offset.

```csharp
using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class TwinStickController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 7f;
    [SerializeField] private float acceleration = 50f;
    [SerializeField] private float turnSpeed = 1080f;
    [SerializeField] private float gravity = -20f;
    [SerializeField] private Camera viewCamera;
    [SerializeField] private bool cameraFollows = true;
    [SerializeField] private Vector3 cameraOffset = new Vector3(0f, 14f, -6f);
    [SerializeField] private float cameraSmoothing = 8f;

    private CharacterController controller;
    private Vector3 velocity;
    private float verticalVelocity;

    public Vector3 AimPoint { get; private set; }

    private void Start()
    {
        controller = GetComponent<CharacterController>();
        if (viewCamera == null) viewCamera = Camera.main;
        AimPoint = transform.position + transform.forward;
    }

    private void Update()
    {
        Vector3 input = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical"));
        Vector3 wanted = Vector3.ClampMagnitude(input, 1f) * moveSpeed;
        velocity = Vector3.MoveTowards(velocity, wanted, acceleration * Time.deltaTime);

        if (controller.isGrounded && verticalVelocity < 0f) verticalVelocity = -2f;
        verticalVelocity += gravity * Time.deltaTime;
        controller.Move((velocity + Vector3.up * verticalVelocity) * Time.deltaTime);

        AimAtMouse();
    }

    private void AimAtMouse()
    {
        if (viewCamera == null) return;
        Plane aimPlane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        Ray ray = viewCamera.ScreenPointToRay(Input.mousePosition);
        float enter;
        if (!aimPlane.Raycast(ray, out enter)) return;

        AimPoint = ray.GetPoint(enter);
        Vector3 direction = AimPoint - transform.position;
        direction.y = 0f;
        if (direction.sqrMagnitude < 0.01f) return;
        Quaternion target = Quaternion.LookRotation(direction);
        transform.rotation = Quaternion.RotateTowards(transform.rotation, target, turnSpeed * Time.deltaTime);
    }

    private void LateUpdate()
    {
        if (!cameraFollows || viewCamera == null) return;
        Vector3 desired = transform.position + cameraOffset;
        viewCamera.transform.position = Vector3.Lerp(viewCamera.transform.position, desired, 1f - Mathf.Exp(-cameraSmoothing * Time.deltaTime));
        viewCamera.transform.rotation = Quaternion.LookRotation(transform.position - viewCamera.transform.position);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawLine(transform.position + Vector3.up, AimPoint + Vector3.up);
        Gizmos.DrawWireSphere(AimPoint, 0.25f);
    }
}
```

Mouse position is a point on the screen, so the script turns it into a ray and finds where the ray crosses a flat plane at the character's height; that gives a true world position under the cursor regardless of camera angle or zoom. Movement is on world axes so WASD always means screen-up, left, down and right in a top-down view, and the two inputs are independent, which is what makes it twin-stick. `AimPoint` is public for weapons to fire towards.

**Plan**
- A small state machine (Normal, Hanging, Climbing) on a `CharacterController`; Normal has simple WASD movement and jump so the file works on its own.
- While falling, a forward ray at chest height finds a vertical wall, then a downward ray just past the wall finds the ledge top; the ledge must be 1.2-2.2 m above the feet, flat, and have room for the capsule to stand.
- Hanging snaps the character to hang under the ledge facing the wall; W or Space starts a 0.6 s climb (up, then forward onto the ledge) and S or C drops.

```csharp
using System.Collections;
using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class LedgeGrabController : MonoBehaviour
{
    private enum State { Normal, Hanging, Climbing }

    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpHeight = 1.3f;
    [SerializeField] private float gravity = -20f;
    [SerializeField] private float chestHeight = 1.3f;
    [SerializeField] private float reach = 0.7f;
    [SerializeField] private float minLedgeHeight = 1.2f;
    [SerializeField] private float maxLedgeHeight = 2.2f;
    [SerializeField] private float hangOffset = 0.45f;
    [SerializeField] private float hangDrop = 1.75f;
    [SerializeField] private float climbTime = 0.6f;
    [SerializeField] private LayerMask solidMask = ~0;

    private State state = State.Normal;
    private CharacterController controller;
    private float verticalVelocity;
    private float nextGrabTime;
    private Vector3 hangPosition;
    private Quaternion hangRotation;
    private Vector3 climbTarget;

    private void Start()
    {
        controller = GetComponent<CharacterController>();
    }

    private void Update()
    {
        if (state == State.Normal)
        {
            Walk();
            if (!controller.isGrounded && verticalVelocity < 0f && Time.time >= nextGrabTime) TryGrab();
        }
        else if (state == State.Hanging)
        {
            transform.position = Vector3.Lerp(transform.position, hangPosition, 15f * Time.deltaTime);
            transform.rotation = Quaternion.Slerp(transform.rotation, hangRotation, 15f * Time.deltaTime);
            if (Input.GetKeyDown(KeyCode.W) || Input.GetButtonDown("Jump")) StartCoroutine(Climb());
            else if (Input.GetKeyDown(KeyCode.S) || Input.GetKeyDown(KeyCode.C)) Release();
        }
    }

    private void Walk()
    {
        Vector3 input = new Vector3(Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical"));
        Vector3 move = Vector3.ClampMagnitude(input, 1f) * moveSpeed;
        if (move.sqrMagnitude > 0.01f)
            transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.LookRotation(move), 720f * Time.deltaTime);
        if (controller.isGrounded && verticalVelocity < 0f) verticalVelocity = -2f;
        if (controller.isGrounded && Input.GetButtonDown("Jump")) verticalVelocity = Mathf.Sqrt(jumpHeight * -2f * gravity);
        verticalVelocity += gravity * Time.deltaTime;
        controller.Move((move + Vector3.up * verticalVelocity) * Time.deltaTime);
    }

    private void TryGrab()
    {
        Vector3 chest = transform.position + Vector3.up * chestHeight;
        RaycastHit wall;
        if (!Physics.Raycast(chest, transform.forward, out wall, reach, solidMask, QueryTriggerInteraction.Ignore)) return;
        if (Mathf.Abs(wall.normal.y) > 0.3f) return;

        float startY = transform.position.y + maxLedgeHeight + 0.4f;
        Vector3 origin = new Vector3(wall.point.x, startY, wall.point.z) - wall.normal * 0.2f;
        RaycastHit top;
        if (!Physics.Raycast(origin, Vector3.down, out top, maxLedgeHeight + 0.4f - minLedgeHeight, solidMask, QueryTriggerInteraction.Ignore)) return;
        if (top.normal.y < 0.7f) return;

        Vector3 stand = top.point + Vector3.up * 0.05f - wall.normal * 0.4f;
        float r = controller.radius * 0.9f;
        if (Physics.CheckCapsule(stand + Vector3.up * r, stand + Vector3.up * (controller.height - r), r, solidMask, QueryTriggerInteraction.Ignore)) return;

        Vector3 flatNormal = new Vector3(wall.normal.x, 0f, wall.normal.z).normalized;
        hangPosition = new Vector3(wall.point.x, top.point.y - hangDrop, wall.point.z) + flatNormal * hangOffset;
        hangRotation = Quaternion.LookRotation(-flatNormal);
        climbTarget = stand;
        verticalVelocity = 0f;
        controller.enabled = false;
        state = State.Hanging;
    }

    private IEnumerator Climb()
    {
        state = State.Climbing;
        Vector3 start = transform.position;
        Vector3 above = new Vector3(start.x, climbTarget.y, start.z);
        for (float t = 0f; t < climbTime; t += Time.deltaTime)
        {
            float n = t / climbTime;
            transform.position = n < 0.6f
                ? Vector3.Lerp(start, above, n / 0.6f)
                : Vector3.Lerp(above, climbTarget, (n - 0.6f) / 0.4f);
            yield return null;
        }
        transform.position = climbTarget;
        controller.enabled = true;
        state = State.Normal;
    }

    private void Release()
    {
        controller.enabled = true;
        state = State.Normal;
        nextGrabTime = Time.time + 0.6f;
    }
}
```

Two rays do the detection: the first confirms there is a near-vertical wall in front of the chest, the second drops from above and just inside the wall to find the walkable top of the ledge. Checking the capsule at the standing position prevents grabbing ledges with a ceiling or object on top, and the `CharacterController` is switched off while hanging and climbing so the script can place the character exactly. After letting go there is a 0.6 s grab cooldown so the player falls instead of re-grabbing the same ledge.

**Plan**
- An enum state machine with Idle, Patrol, Chase and Attack, driven by the distance to the player and a `NavMeshAgent`.
- Idle waits 2 s and then patrols to the next waypoint; Patrol walks to the current waypoint, then returns to Idle; seeing the player within `detectRange` switches to Chase (faster speed); within `attackRange` it stops and attacks on a cooldown.
- Losing the player (beyond `loseRange`) returns to Idle; damage is delivered with `SendMessage("TakeDamage")`, and gizmos show the ranges.

```csharp
using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class EnemyStateMachine : MonoBehaviour
{
    public enum State { Idle, Patrol, Chase, Attack }

    [SerializeField] private Transform player;
    [SerializeField] private Transform[] patrolPoints;
    [SerializeField] private float idleTime = 2f;
    [SerializeField] private float patrolSpeed = 2f;
    [SerializeField] private float chaseSpeed = 4.5f;
    [SerializeField] private float detectRange = 12f;
    [SerializeField] private float loseRange = 18f;
    [SerializeField] private float attackRange = 1.8f;
    [SerializeField] private float attackCooldown = 1f;
    [SerializeField] private float attackDamage = 10f;

    private NavMeshAgent agent;
    private State state;
    private int pointIndex;
    private float stateTimer;
    private float nextAttack;

    public State Current { get { return state; } }

    private void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        if (player == null)
        {
            GameObject found = GameObject.FindWithTag("Player");
            if (found != null) player = found.transform;
        }
        Enter(State.Idle);
    }

    private void Update()
    {
        float distance = player != null ? Vector3.Distance(transform.position, player.position) : float.MaxValue;
        switch (state)
        {
            case State.Idle:
                stateTimer -= Time.deltaTime;
                if (distance <= detectRange) Enter(State.Chase);
                else if (stateTimer <= 0f && patrolPoints.Length > 0) Enter(State.Patrol);
                break;
            case State.Patrol:
                if (distance <= detectRange) Enter(State.Chase);
                else if (!agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.1f)
                {
                    pointIndex = (pointIndex + 1) % patrolPoints.Length;
                    Enter(State.Idle);
                }
                break;
            case State.Chase:
                agent.SetDestination(player.position);
                if (distance <= attackRange) Enter(State.Attack);
                else if (distance > loseRange) Enter(State.Idle);
                break;
            case State.Attack:
                FaceTarget();
                if (distance > attackRange * 1.3f) Enter(State.Chase);
                else if (Time.time >= nextAttack)
                {
                    nextAttack = Time.time + attackCooldown;
                    player.SendMessage("TakeDamage", attackDamage, SendMessageOptions.DontRequireReceiver);
                }
                break;
        }
    }

    private void Enter(State next)
    {
        state = next;
        switch (next)
        {
            case State.Idle:
                agent.isStopped = true;
                stateTimer = idleTime;
                break;
            case State.Patrol:
                agent.isStopped = false;
                agent.speed = patrolSpeed;
                agent.SetDestination(patrolPoints[pointIndex].position);
                break;
            case State.Chase:
                agent.isStopped = false;
                agent.speed = chaseSpeed;
                break;
            case State.Attack:
                agent.isStopped = true;
                break;
        }
    }

    private void FaceTarget()
    {
        Vector3 direction = player.position - transform.position;
        direction.y = 0f;
        if (direction.sqrMagnitude > 0.01f)
            transform.rotation = Quaternion.Slerp(transform.rotation, Quaternion.LookRotation(direction), 10f * Time.deltaTime);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, detectRange);
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, attackRange);
    }
}
```

All state changes go through one `Enter` method, so everything that must happen once on entry (setting speed, stopping or resuming the agent, choosing a destination) lives in one place, and `Update` only decides when to leave a state. Using a larger lose range than detect range, and a slightly larger range to leave Attack than to enter it, adds hysteresis so the enemy does not flicker between states at the boundary. Bake a NavMesh in the scene for the agent to use.

**Plan**
- The enemy checks three things in order: the player is within `viewDistance`, within half of `viewAngle` of the eye's forward direction, and a raycast from the eye to the player's chest is not blocked by anything in `obstacleMask`.
- A `memoryTime` keeps the enemy alerted for a couple of seconds after the player leaves view, remembering `LastKnownPosition`, and it turns toward that spot.
- The enemy's renderer is tinted green/orange/red for unaware/alerted/seeing, and a gizmo draws the cone.

```csharp
using UnityEngine;

public class VisionConeEnemy : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private Transform eye;
    [SerializeField] private float viewDistance = 15f;
    [SerializeField, Range(10f, 180f)] private float viewAngle = 90f;
    [SerializeField] private LayerMask obstacleMask = ~0;
    [SerializeField] private float chestHeight = 1f;
    [SerializeField] private float memoryTime = 2f;
    [SerializeField] private float turnSpeed = 180f;

    private float lastSeenTime = -999f;
    private Renderer body;

    public bool CanSeePlayer { get; private set; }
    public Vector3 LastKnownPosition { get; private set; }
    public bool IsAlerted { get { return Time.time - lastSeenTime < memoryTime; } }

    private void Start()
    {
        if (player == null)
        {
            GameObject found = GameObject.FindWithTag("Player");
            if (found != null) player = found.transform;
        }
        if (eye == null) eye = transform;
        body = GetComponentInChildren<Renderer>();
    }

    private void Update()
    {
        CanSeePlayer = player != null && CheckVision();
        if (CanSeePlayer)
        {
            lastSeenTime = Time.time;
            LastKnownPosition = player.position;
        }

        if (IsAlerted)
        {
            Vector3 direction = LastKnownPosition - transform.position;
            direction.y = 0f;
            if (direction.sqrMagnitude > 0.01f)
                transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.LookRotation(direction), turnSpeed * Time.deltaTime);
        }

        if (body != null)
            body.material.color = CanSeePlayer ? Color.red : IsAlerted ? new Color(1f, 0.6f, 0.1f) : Color.green;
    }

    private bool CheckVision()
    {
        Vector3 target = player.position + Vector3.up * chestHeight;
        Vector3 toTarget = target - eye.position;
        float distance = toTarget.magnitude;
        if (distance > viewDistance) return false;
        if (Vector3.Angle(eye.forward, toTarget) > viewAngle * 0.5f) return false;

        RaycastHit hit;
        if (Physics.Raycast(eye.position, toTarget / distance, out hit, distance, obstacleMask, QueryTriggerInteraction.Ignore))
            return hit.transform == player || hit.transform.IsChildOf(player);
        return true;
    }

    private void OnDrawGizmosSelected()
    {
        Transform origin = eye != null ? eye : transform;
        Gizmos.color = Color.yellow;
        Vector3 left = Quaternion.Euler(0f, -viewAngle * 0.5f, 0f) * origin.forward * viewDistance;
        Vector3 right = Quaternion.Euler(0f, viewAngle * 0.5f, 0f) * origin.forward * viewDistance;
        Gizmos.DrawRay(origin.position, left);
        Gizmos.DrawRay(origin.position, right);
        Gizmos.DrawLine(origin.position + left, origin.position + right);
    }
}
```

The cone test is just an angle: `Vector3.Angle` between where the eye faces and the direction to the player, compared with half the field of view. The raycast then takes care of walls, and its result is accepted only if the first thing it hits is the player, so crates and doors block sight. The memory timer stops the enemy from instantly forgetting the player for a single frame of lost sight.

**Plan**
- The companion keeps a `NavMeshAgent` stopping distance of `followDistance` and re-targets the player's position every 0.2 s, but only starts moving when the player gets more than 1 m past that distance (hysteresis), so it does not jitter in place.
- Its speed scales from `baseSpeed` up to double as the distance grows toward `catchUpDistance`, and if the distance exceeds `warpDistance` it warps to the nearest NavMesh point behind the player.
- While standing still it slowly turns to face the player.

```csharp
using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class CompanionFollower : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private float followDistance = 3f;
    [SerializeField] private float resumeMargin = 1f;
    [SerializeField] private float catchUpDistance = 10f;
    [SerializeField] private float warpDistance = 30f;
    [SerializeField] private float baseSpeed = 3.5f;
    [SerializeField] private float maxSpeedMultiplier = 2f;
    [SerializeField] private float repathInterval = 0.2f;

    private NavMeshAgent agent;
    private float nextRepath;
    private bool moving;

    private void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        agent.stoppingDistance = followDistance;
        if (player == null)
        {
            GameObject found = GameObject.FindWithTag("Player");
            if (found != null) player = found.transform;
        }
    }

    private void Update()
    {
        if (player == null || !agent.isOnNavMesh) return;

        Vector3 offset = player.position - transform.position;
        offset.y = 0f;
        float distance = offset.magnitude;

        if (distance > warpDistance)
        {
            WarpBehindPlayer();
            return;
        }

        float t = Mathf.InverseLerp(followDistance, catchUpDistance, distance);
        agent.speed = Mathf.Lerp(baseSpeed, baseSpeed * maxSpeedMultiplier, t);

        if (!moving && distance > followDistance + resumeMargin) moving = true;
        else if (moving && distance <= followDistance) moving = false;

        if (moving)
        {
            if (Time.time >= nextRepath)
            {
                nextRepath = Time.time + repathInterval;
                agent.isStopped = false;
                agent.SetDestination(player.position);
            }
        }
        else
        {
            agent.isStopped = true;
            if (offset.sqrMagnitude > 0.01f)
                transform.rotation = Quaternion.Slerp(transform.rotation, Quaternion.LookRotation(offset), 4f * Time.deltaTime);
        }
    }

    private void WarpBehindPlayer()
    {
        NavMeshHit hit;
        Vector3 wanted = player.position - player.forward * followDistance;
        if (NavMesh.SamplePosition(wanted, out hit, 4f, NavMesh.AllAreas)) agent.Warp(hit.position);
    }
}
```

Giving the agent a stopping distance makes the NavMesh stop it at the right range on its own, and the two thresholds (start moving at 4 m, stop at 3 m) prevent the stop-start flicker that a single threshold causes when the player stands still. The speed ramp lets it sprint to catch up and then settle to walking pace, and `Warp` teleports it without breaking the agent when it has been left far behind (after a respawn or a fast ride).

**Plan**
- Every frame the turret uses `Physics.OverlapSphere` with an enemy layer mask to find colliders in range and picks the closest one; if the mask is empty it falls back to a layer named "Enemy".
- The turret head turns toward the target with `RotateTowards` at a limited speed and fires at `fireRate` shots per second only when it is within a few degrees of facing the target.
- Shots are hitscan raycasts from the muzzle; a hit sends `TakeDamage` to the target, and a short-lived stretched cube acts as the tracer.

```csharp
using UnityEngine;

public class AutoTurret : MonoBehaviour
{
    [SerializeField] private Transform head;
    [SerializeField] private Transform muzzle;
    [SerializeField] private float range = 20f;
    [SerializeField] private float turnSpeed = 180f;
    [SerializeField] private float fireRate = 4f;
    [SerializeField] private float damage = 8f;
    [SerializeField] private float aimTolerance = 4f;
    [SerializeField] private LayerMask enemyMask;

    private float nextFire;

    public Transform Target { get; private set; }

    private void Start()
    {
        if (head == null) head = transform;
        if (muzzle == null) muzzle = head;
        if (enemyMask.value == 0)
        {
            int layer = LayerMask.NameToLayer("Enemy");
            if (layer >= 0) enemyMask = 1 << layer;
        }
    }

    private void Update()
    {
        Target = FindClosestEnemy();
        if (Target == null) return;

        Vector3 aimPoint = Target.position + Vector3.up * 0.8f;
        Vector3 direction = aimPoint - head.position;
        Quaternion wanted = Quaternion.LookRotation(direction);
        head.rotation = Quaternion.RotateTowards(head.rotation, wanted, turnSpeed * Time.deltaTime);

        if (Vector3.Angle(head.forward, direction) <= aimTolerance && Time.time >= nextFire)
        {
            nextFire = Time.time + 1f / fireRate;
            Fire();
        }
    }

    private Transform FindClosestEnemy()
    {
        Transform closest = null;
        float bestSqr = float.MaxValue;
        foreach (Collider c in Physics.OverlapSphere(transform.position, range, enemyMask, QueryTriggerInteraction.Ignore))
        {
            if (c.transform.IsChildOf(transform)) continue;
            float sqr = (c.transform.position - transform.position).sqrMagnitude;
            if (sqr < bestSqr)
            {
                bestSqr = sqr;
                closest = c.transform;
            }
        }
        return closest;
    }

    private void Fire()
    {
        Vector3 end = muzzle.position + muzzle.forward * range;
        RaycastHit hit;
        if (Physics.Raycast(muzzle.position, muzzle.forward, out hit, range * 1.2f, ~0, QueryTriggerInteraction.Ignore) && !hit.transform.IsChildOf(transform))
        {
            end = hit.point;
            hit.collider.SendMessageUpwards("TakeDamage", damage, SendMessageOptions.DontRequireReceiver);
        }
        SpawnTracer(muzzle.position, end);
    }

    private static void SpawnTracer(Vector3 from, Vector3 to)
    {
        GameObject tracer = GameObject.CreatePrimitive(PrimitiveType.Cube);
        Destroy(tracer.GetComponent<Collider>());
        Vector3 delta = to - from;
        tracer.transform.position = from + delta * 0.5f;
        tracer.transform.rotation = Quaternion.LookRotation(delta);
        tracer.transform.localScale = new Vector3(0.04f, 0.04f, delta.magnitude);
        tracer.GetComponent<Renderer>().material.color = new Color(1f, 0.9f, 0.3f);
        Destroy(tracer, 0.05f);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.cyan;
        Gizmos.DrawWireSphere(transform.position, range);
    }
}
```

The turret only fires when it is actually looking at the target (within `aimTolerance` degrees), so it visibly tracks before shooting, and the rate limiter `1 / fireRate` makes `fireRate` mean shots per second. Put enemies on a layer named Enemy (or set the mask in the inspector) so the sphere query ignores terrain and other objects, and give enemies a `TakeDamage(float)` method.

**Plan**
- A coroutine runs the waves: a countdown between waves, then `firstWaveSize + (wave - 1) * increasePerWave` enemies spawned one every 0.4 s at random spawn points.
- The next wave only starts once every enemy of the current wave is gone (destroyed or null), then the countdown begins again; `maxWaves = 0` means endless.
- A UI Toolkit label shows the countdown or "Wave n - enemies left: x"; if no prefab is given a red cube enemy is used and clicking it destroys it for testing.

```csharp
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

public class WaveSpawner : MonoBehaviour
{
    [SerializeField] private GameObject enemyPrefab;
    [SerializeField] private Transform[] spawnPoints;
    [SerializeField] private int firstWaveSize = 3;
    [SerializeField] private int increasePerWave = 2;
    [SerializeField] private int maxWaves = 10;
    [SerializeField] private float timeBetweenWaves = 5f;
    [SerializeField] private float spawnInterval = 0.4f;

    private readonly List<GameObject> alive = new List<GameObject>();
    private Label status;

    public int CurrentWave { get; private set; }
    public event Action<int> OnWaveStarted;
    public event Action OnAllWavesCleared;

    private void Start()
    {
        BuildUi();
        StartCoroutine(RunWaves());
    }

    private void Update()
    {
        // Test helper for the default enemy: click one to destroy it.
        if (enemyPrefab != null || !Input.GetMouseButtonDown(0) || Camera.main == null) return;
        RaycastHit hit;
        if (Physics.Raycast(Camera.main.ScreenPointToRay(Input.mousePosition), out hit) && alive.Contains(hit.collider.gameObject))
            Destroy(hit.collider.gameObject);
    }

    private IEnumerator RunWaves()
    {
        while (maxWaves == 0 || CurrentWave < maxWaves)
        {
            for (float t = timeBetweenWaves; t > 0f; t -= Time.deltaTime)
            {
                status.text = "Wave " + (CurrentWave + 1) + " in " + Mathf.CeilToInt(t);
                yield return null;
            }

            CurrentWave++;
            int count = firstWaveSize + (CurrentWave - 1) * increasePerWave;
            if (OnWaveStarted != null) OnWaveStarted(CurrentWave);
            for (int i = 0; i < count; i++)
            {
                alive.Add(SpawnEnemy());
                status.text = "Wave " + CurrentWave + " - enemies left: " + AliveCount();
                yield return new WaitForSeconds(spawnInterval);
            }

            while (AliveCount() > 0)
            {
                status.text = "Wave " + CurrentWave + " - enemies left: " + AliveCount();
                yield return null;
            }
        }
        status.text = "All waves cleared!";
        if (OnAllWavesCleared != null) OnAllWavesCleared();
    }

    private int AliveCount()
    {
        alive.RemoveAll(enemy => enemy == null);
        return alive.Count;
    }

    private GameObject SpawnEnemy()
    {
        Vector3 position = transform.position;
        if (spawnPoints != null && spawnPoints.Length > 0)
            position = spawnPoints[UnityEngine.Random.Range(0, spawnPoints.Length)].position;

        GameObject enemy;
        if (enemyPrefab != null)
        {
            enemy = Instantiate(enemyPrefab, position, Quaternion.identity);
        }
        else
        {
            enemy = GameObject.CreatePrimitive(PrimitiveType.Cube);
            enemy.transform.position = position + Vector3.up * 0.5f;
            enemy.GetComponent<Renderer>().material.color = Color.red;
        }
        return enemy;
    }

    private void BuildUi()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        doc.rootVisualElement.pickingMode = PickingMode.Ignore;
        status = new Label();
        status.style.position = Position.Absolute;
        status.style.top = 24;
        status.style.alignSelf = Align.Center;
        status.style.fontSize = 36;
        status.style.color = Color.white;
        doc.rootVisualElement.Add(status);
    }
}
