The size of each wave is a simple formula, so balancing means changing two numbers. Counting alive enemies by removing destroyed (null) objects from a list lets any damage system finish a wave just by destroying its enemy, and waiting for the list to empty before the countdown means waves never overlap. The coroutine form keeps the whole wave logic readable as one top-to-bottom loop.

**Plan**
- Spawn `fishCount` fish as small stretched cubes at random points inside a box (the box is `transform.position` plus `boxSize`), each with a random starting velocity.
- Each frame every fish steers with separation, alignment and cohesion from neighbours inside `neighbourRadius`, plus a wall-avoidance force that grows as it nears a face of the box.
- Velocity is clamped between a minimum and maximum speed and each fish turns to face its movement; a wireframe gizmo draws the box.

```csharp
using UnityEngine;

public class FishSchool : MonoBehaviour
{
    [SerializeField] private int fishCount = 60;
    [SerializeField] private Vector3 boxSize = new Vector3(30f, 14f, 30f);
    [SerializeField] private float neighbourRadius = 5f;
    [SerializeField] private float separationRadius = 1.5f;
    [SerializeField] private float minSpeed = 2f;
    [SerializeField] private float maxSpeed = 5f;
    [SerializeField] private float separationWeight = 2.5f;
    [SerializeField] private float alignmentWeight = 1f;
    [SerializeField] private float cohesionWeight = 0.8f;
    [SerializeField] private float wallMargin = 4f;
    [SerializeField] private float wallForce = 10f;

    private Transform[] fish;
    private Vector3[] velocity;
    private Vector3[] acceleration;

    private void Start()
    {
        fish = new Transform[fishCount];
        velocity = new Vector3[fishCount];
        acceleration = new Vector3[fishCount];
        for (int i = 0; i < fishCount; i++)
        {
            GameObject f = GameObject.CreatePrimitive(PrimitiveType.Cube);
            Destroy(f.GetComponent<Collider>());
            f.transform.SetParent(transform, false);
            f.transform.localScale = new Vector3(0.15f, 0.3f, 0.7f);
            f.transform.position = transform.position + new Vector3(
                Random.Range(-boxSize.x, boxSize.x), Random.Range(-boxSize.y, boxSize.y), Random.Range(-boxSize.z, boxSize.z)) * 0.4f;
            f.GetComponent<Renderer>().material.color = Color.HSVToRGB(Random.Range(0.5f, 0.6f), 0.6f, 1f);
            fish[i] = f.transform;
            velocity[i] = Random.onUnitSphere * Random.Range(minSpeed, maxSpeed);
        }
    }

    private void Update()
    {
        for (int i = 0; i < fishCount; i++) acceleration[i] = Steer(i) + AvoidWalls(fish[i].position);

        for (int i = 0; i < fishCount; i++)
        {
            Vector3 v = velocity[i] + acceleration[i] * Time.deltaTime;
            float speed = Mathf.Clamp(v.magnitude, minSpeed, maxSpeed);
            velocity[i] = v.sqrMagnitude > 0.0001f ? v.normalized * speed : velocity[i];
            fish[i].position += velocity[i] * Time.deltaTime;
            fish[i].rotation = Quaternion.Slerp(fish[i].rotation, Quaternion.LookRotation(velocity[i]), 8f * Time.deltaTime);
        }
    }

    private Vector3 Steer(int index)
    {
        Vector3 position = fish[index].position;
        Vector3 separation = Vector3.zero, velocitySum = Vector3.zero, positionSum = Vector3.zero;
        int neighbours = 0;
        for (int j = 0; j < fishCount; j++)
        {
            if (j == index) continue;
            Vector3 offset = fish[j].position - position;
            float distance = offset.magnitude;
            if (distance > neighbourRadius || distance < 0.0001f) continue;
            neighbours++;
            velocitySum += velocity[j];
            positionSum += fish[j].position;
            if (distance < separationRadius) separation -= offset / (distance * distance);
        }
        if (neighbours == 0) return Vector3.zero;
        Vector3 alignment = velocitySum / neighbours - velocity[index];
        Vector3 cohesion = positionSum / neighbours - position;
        return separation * separationWeight + alignment * alignmentWeight + cohesion * cohesionWeight;
    }

    private Vector3 AvoidWalls(Vector3 position)
    {
        Vector3 local = position - transform.position;
        Vector3 half = boxSize * 0.5f;
        Vector3 force = Vector3.zero;
        force.x = Push(local.x, half.x);
        force.y = Push(local.y, half.y);
        force.z = Push(local.z, half.z);
        return force;
    }

    private float Push(float value, float half)
    {
        float over = Mathf.Abs(value) - (half - wallMargin);
        if (over <= 0f) return 0f;
        return -Mathf.Sign(value) * Mathf.Clamp01(over / wallMargin) * wallForce;
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.cyan;
        Gizmos.DrawWireCube(transform.position, boxSize);
    }
}
```

Each fish only looks at neighbours within a radius, which produces local groups that merge and split, and the three weights are the whole personality of the school: raise separation for a loose swarm, cohesion for a tight ball. The wall force ramps up smoothly inside the margin instead of bouncing at the face, so the fish curve away like real fish. All accelerations are calculated before any position is changed, so the result does not depend on update order.

**Plan**
