```csharp
using System.Collections.Generic;
using UnityEngine;

public class ProjectileLauncher : MonoBehaviour
{
    [SerializeField] private Transform muzzle;
    [SerializeField] private int poolSize = 20;
    [SerializeField] private float speed = 30f;
    [SerializeField] private float lifetime = 3f;
    [SerializeField] private float fireRate = 6f;
    [SerializeField] private float damage = 10f;

    private readonly Queue<PooledProjectile> pool = new Queue<PooledProjectile>();
    private Transform container;
    private float nextShot;

    public int Available { get { return pool.Count; } }

    private void Start()
    {
        if (muzzle == null) muzzle = transform;
        container = new GameObject("ProjectilePool").transform;
        for (int i = 0; i < poolSize; i++) pool.Enqueue(Create());
    }

    private void Update()
    {
        if (Input.GetMouseButton(0) && Time.time >= nextShot)
        {
            nextShot = Time.time + 1f / fireRate;
            Fire();
        }
    }

    private PooledProjectile Create()
    {
        GameObject sphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        sphere.name = "Projectile";
        sphere.transform.SetParent(container, false);
        sphere.transform.localScale = Vector3.one * 0.3f;
        sphere.GetComponent<Renderer>().material.color = new Color(1f, 0.5f, 0.1f);
        Rigidbody body = sphere.AddComponent<Rigidbody>();
        body.useGravity = false;
        body.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
        PooledProjectile projectile = sphere.AddComponent<PooledProjectile>();
        projectile.Setup(this, damage);
        sphere.SetActive(false);
        return projectile;
    }

    private void Fire()
    {
        PooledProjectile projectile = pool.Count > 0 ? pool.Dequeue() : Create();
        projectile.Launch(muzzle.position, muzzle.forward * speed, lifetime);
    }

    public void Return(PooledProjectile projectile)
    {
        projectile.gameObject.SetActive(false);
        pool.Enqueue(projectile);
    }
}

// Helper behaviour; it is only ever added to pooled spheres at runtime by the launcher above.
public class PooledProjectile : MonoBehaviour
{
    private ProjectileLauncher owner;
    private Rigidbody body;
    private float damage;
    private float expireAt;
    private bool active;

    public void Setup(ProjectileLauncher launcher, float hitDamage)
    {
        owner = launcher;
        damage = hitDamage;
        body = GetComponent<Rigidbody>();
    }

    public void Launch(Vector3 position, Vector3 velocity, float lifetime)
    {
        transform.position = position;
        gameObject.SetActive(true);
        body.velocity = velocity;
        body.angularVelocity = Vector3.zero;
        expireAt = Time.time + lifetime;
        active = true;
    }

    private void Update()
    {
        if (active && Time.time >= expireAt) Finish();
    }

    private void OnCollisionEnter(Collision collision)
    {
        if (!active) return;
        collision.collider.SendMessageUpwards("TakeDamage", damage, SendMessageOptions.DontRequireReceiver);
        Finish();
    }

    private void Finish()
    {
        active = false;
        body.velocity = Vector3.zero;
        owner.Return(this);
    }
}
```

Object pooling avoids creating and destroying objects while the player fires, which is what causes garbage-collection hitches in fast shooters. The `active` flag stops a projectile from being returned twice when a collision and the lifetime expiry happen in the same frame, which would put the same object in the queue twice, and continuous collision detection keeps fast projectiles from passing through thin walls.

**Plan**
- An `IDamageable` interface with `TakeDamage(float amount)` and `IsDead` is the only thing attackers know about.
- Three implementations: `PlayerHealth` (takes 25% less damage from armour), `EnemyHealth` (dies and is destroyed), and `BreakableCrate` (breaks after several hits and shrinks).
- A demo MonoBehaviour spawns one of each as cubes and lets you left click any of them; the click calls `GetComponentInParent<IDamageable>()` and never checks the concrete type.

```csharp
using UnityEngine;

public interface IDamageable
{
    bool IsDead { get; }
    void TakeDamage(float amount);
}

public class DamageableDemo : MonoBehaviour
{
    [SerializeField] private float clickDamage = 15f;

    private void Start()
    {
        Spawn<PlayerHealth>("Player", new Vector3(-3f, 0.5f, 0f), Color.green);
        Spawn<EnemyHealth>("Enemy", new Vector3(0f, 0.5f, 0f), Color.red);
        Spawn<BreakableCrate>("Crate", new Vector3(3f, 0.5f, 0f), new Color(0.6f, 0.4f, 0.2f));
        if (Camera.main != null)
        {
            Camera.main.transform.position = new Vector3(0f, 3f, -9f);
            Camera.main.transform.LookAt(Vector3.zero);
        }
    }

    private void Update()
    {
        if (!Input.GetMouseButtonDown(0) || Camera.main == null) return;
        RaycastHit hit;
        if (!Physics.Raycast(Camera.main.ScreenPointToRay(Input.mousePosition), out hit)) return;
        IDamageable target = hit.collider.GetComponentInParent<IDamageable>();
        if (target != null && !target.IsDead) target.TakeDamage(clickDamage);
    }

    private static void Spawn<T>(string name, Vector3 position, Color color) where T : Component
    {
        GameObject cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
        cube.name = name;
        cube.transform.position = position;
        cube.GetComponent<Renderer>().material.color = color;
        cube.AddComponent<T>();
    }
}

public class PlayerHealth : MonoBehaviour, IDamageable
{
    private float health = 100f;
    private const float Armor = 0.25f;

    public bool IsDead { get { return health <= 0f; } }

    public void TakeDamage(float amount)
    {
        health -= amount * (1f - Armor);
        Debug.Log(name + " health: " + Mathf.Max(0f, health).ToString("0"));
        if (IsDead) GetComponent<Renderer>().material.color = Color.gray;
    }
}

public class EnemyHealth : MonoBehaviour, IDamageable
{
    private float health = 45f;

    public bool IsDead { get { return health <= 0f; } }

    public void TakeDamage(float amount)
    {
        health -= amount;
        GetComponent<Renderer>().material.color = Color.Lerp(Color.black, Color.red, Mathf.Clamp01(health / 45f));
        if (IsDead) Destroy(gameObject, 0.1f);
    }
}

public class BreakableCrate : MonoBehaviour, IDamageable
{
    private int hitsLeft = 3;

    public bool IsDead { get { return hitsLeft <= 0; } }

    public void TakeDamage(float amount)
    {
        hitsLeft--;
        transform.localScale *= 0.75f;
        if (IsDead) Destroy(gameObject);
    }
}
```

Attackers (here the click handler, in a real game bullets, swords and explosions) depend only on the interface, so a new thing that can be hurt, such as a door or a boss, needs nothing but a new class that implements it and no change to any weapon. Each class decides what damage means for itself: armour for the player, a death for the enemy, a hit counter for the crate. Use `GetComponentInParent` so that hitting a child collider still finds the damage component on the parent.
